function minimumSwap(s1, s2) {
  // Breadth-first search over every pair of strings reachable by cross swaps.
  const n = s1.length;
  const key = (a, b) => a + '|' + b;
  const dist = new Map([[key(s1, s2), 0]]);
  let frontier = [[s1, s2]];
  while (frontier.length) {
    const next = [];
    for (const [a, b] of frontier) {
      const d = dist.get(key(a, b));
      if (a === b) return d;
      for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
          if (a[i] === b[j]) continue;
          const na = a.slice(0, i) + b[j] + a.slice(i + 1);
          const nb = b.slice(0, j) + a[i] + b.slice(j + 1);
          const k = key(na, nb);
          if (!dist.has(k)) { dist.set(k, d + 1); next.push([na, nb]); }
        }
      }
    }
    frontier = next;
  }
  return -1;
}

