function generate(rand, size) {
  const n = size === 'large' ? 800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 6);
  const pick = () => (rand() < 0.5 ? 'x' : 'y');
  const same = rand() * 0.6;
  let s1 = '';
  let s2 = '';
  for (let i = 0; i < n; i++) {
    const c = pick();
    s1 += c;
    s2 += rand() < same ? c : pick();
  }
  return [s1, s2];
}
